import numpy as np, pandas as pd
def model(regime, n, seed):
    s = float((regime.config or {}).get("speed", 1.0)); s=min(max(s,0.8),1.4)
    lam = 6.5*s**0.96
    rng = np.random.default_rng(seed)
    return pd.DataFrame({"unit_id": np.arange(int(n),dtype=float), "y": rng.poisson(lam,int(n)).astype(float)})

import numpy as np, pandas as pd
